import React, { useState } from 'react';
import './Career.css';

function Career() {
    const [expandedJob, setExpandedJob] = useState(null);
    const [formData, setFormData] = useState({
        name: '',
        email: '',
        phone: '',
        resume: null,
        message: ''
    });
    const [submitting, setSubmitting] = useState(false);

    const jobs = [
        {
            id: 1,
            title: "Frontend Developer",
            location: "Remote",
            description: "Build sleek, scalable React applications with cutting-edge tools. You’ll work closely with designers and product owners.",
        },
        {
            id: 2,
            title: "Backend Developer",
            location: "Ahmedabad, India",
            description: "Develop robust APIs and handle data management. Proficiency in Node.js, Django, or Laravel preferred.",
        },
        {
            id: 3,
            title: "UI/UX Designer",
            location: "Remote or On-site",
            description: "Design intuitive, attractive interfaces using tools like Figma, Adobe XD, or Sketch.",
        },
    ];

    const toggleExpand = (id) => {
        setExpandedJob(prev => (prev === id ? null : id));
    };

    const handleChange = (e) => {
        const { name, value, files } = e.target;
        setFormData(prev => ({
            ...prev,
            [name]: files ? files[0] : value
        }));
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        setSubmitting(true);

        setTimeout(() => {
            alert("Application submitted!");
            setFormData({ name: '', email: '', phone: '', resume: null, message: '' });
            setSubmitting(false);
        }, 1500);
    };

    return (
        <div className="career-page">
            <section className="hero">
                <h1>Join Chintamani Group</h1>
                <p>Your journey to excellence starts here.</p>
            </section>

            <section className="job-openings">
                <h2>Current Openings</h2>
                <div className="job-grid">
                    {jobs.map((job) => (
                        <div key={job.id} className={`job-card ${expandedJob === job.id ? 'expanded' : ''}`}>
                            <div onClick={() => toggleExpand(job.id)} className="job-header">
                                <h3>{job.title}</h3>
                                <span>{job.location}</span>
                            </div>
                            {expandedJob === job.id && (
                                <div className="job-description">
                                    <p>{job.description}</p>
                                    <button onClick={() => window.scrollTo({ top: document.body.scrollHeight, behavior: 'smooth' })}>
                                        Apply Now
                                    </button>
                                </div>
                            )}
                        </div>
                    ))}
                </div>
            </section>

            <section className="application-form-section">
                <h2>Apply to Join Our Talent Pool</h2>
                <form className="application-form" onSubmit={handleSubmit}>
                    <div className="form-group floating-label">
                        <input type="text" name="name" value={formData.name} onChange={handleChange} required />
                        <label>Name</label>
                    </div>
                    <div className="form-group floating-label">
                        <input type="email" name="email" value={formData.email} onChange={handleChange} required />
                        <label>Email</label>
                    </div>
                    <div className="form-group floating-label">
                        <input type="tel" name="phone" value={formData.phone} onChange={handleChange} required />
                        <label>Phone</label>
                    </div>
                    <div className="form-group">
                        <label>Upload Resume (PDF/DOCX)</label>
                        <input type="file" name="resume" accept=".pdf,.doc,.docx" onChange={handleChange} required />
                        {formData.resume && <p className="file-preview">Selected: {formData.resume.name}</p>}
                    </div>
                    <div className="form-group floating-label">
                        <textarea name="message" value={formData.message} onChange={handleChange} required />
                        <label>Why do you want to join us?</label>
                    </div>
                    <button type="submit" disabled={submitting}>
                        {submitting ? 'Submitting...' : 'Submit Application'}
                    </button>
                    {submitting && <div className="progress-bar"><div className="progress" /></div>}
                </form>
            </section>
        </div>
    );
}

export default Career;
